use moloch_live_runtime::dispatch;
#[path="../src/execution_edge.rs"]mod execution_edge;
use execution_edge::*;
use moloch_replay::session::Session;
use serde_json::{Value,json};
use std::path::PathBuf;
const BASE:u64=1_792_022_400_000;
fn stamp(ms:u64)->String{chrono::DateTime::from_timestamp_millis((BASE+ms)as i64).unwrap().to_rfc3339_opts(chrono::SecondsFormat::Millis,true)}
fn config()->Config{Config{fill_window_ms:1000,markout_ms:1000,post_window_ms:500,embargo_ms:500,maximum_book_age_ms:10_000,maximum_delivery_ms:1000,maximum_training_age_ms:60_000,minimum_samples:2,minimum_coverage_bps:9000,probability_haircut_bps:1000,uncertainty_per_share:5000,exit_fee_per_share:0,fee_policy_source_sha256:"a".repeat(64),maximum_keys:16,maximum_pending:16,retained_samples:8}}
struct F{bank:Session,model:Model,log:dispatch::DispatchLog,path:PathBuf,seq:u64,bookseq:u64}
impl Drop for F{fn drop(&mut self){let _=std::fs::remove_dir_all(&self.path);}}
impl F{
 fn new()->Self{let path=std::env::temp_dir().join(format!("execution-edge-{}-{}",std::process::id(),std::time::SystemTime::now().duration_since(std::time::UNIX_EPOCH).unwrap().as_nanos()));std::fs::create_dir(&path).unwrap();let policy=json!({"initialCash":"100.000000","maximumCommitted":"40.000000","maximumMarketCost":"20.000000","quantity":2,"maximumMarkets":3,"minimumSpreadTicks":2,"entryStopAt":stamp(1_000_000)});let seed=json!({"runId":"edge-fixture","availableCash":"100.000000","accountSnapshotHash":"a".repeat(64),"observedAt":stamp(0)});let bank=Session::open_live(&path.join("bank"),&policy,&seed).unwrap();let model=Model::new(&bank,config()).unwrap();let log=dispatch::DispatchLog::open(&path.join("ordinary.ndjson")).unwrap();Self{bank,model,log,path,seq:0,bookseq:0}}
 fn put(&mut self,mut e:Value,at:u64){e["receivedAt"]=json!(stamp(at));e["processedAt"]=json!(stamp(at));self.seq+=1;assert!(self.bank.accept("actual-fixture",self.seq,&e).unwrap());self.model.observe_committed(&self.bank,"actual-fixture",self.seq,&e).unwrap();}
 fn coverage(&mut self,at:u64){self.put(json!({"type":"coverage","marketId":"101","exchangeId":"101","tournamentId":"cup","from":chrono::DateTime::from_timestamp_millis(BASE as i64-1_000).unwrap().to_rfc3339_opts(chrono::SecondsFormat::Millis,true),"to":stamp(at),"complete":true,"projectedThroughSequence":"999999"}),at);}
 fn book(&mut self,source:u64,observed:u64,bid:&str,ask:&str,quantity:u64){self.bookseq+=1;self.put(json!({"type":"book","book":{"tournamentId":"cup","marketId":"101","exchangeId":"101","sequence":self.bookseq.to_string(),"sourceAt":stamp(source),"requestStartedAt":stamp(source),"receivedAt":stamp(observed),"bids":[{"price":bid,"quantity":quantity}],"asks":[{"price":ask,"quantity":quantity}]}}),observed);}
 fn quote(&self)->Value{self.bank.engine().order_records().into_iter().find(|q|q["retired"]==false&&q["side"]=="YES"&&q["action"]=="buy"&&q["price"]=="0.400000").expect("ordinary original passive YES quote")}
 fn start(&mut self,base:u64)->(Value,Key){self.coverage(base);self.book(base,base,"0.400000","0.450000",100);self.coverage(base+3000);self.book(base+3000,base+3000,"0.400000","0.450000",100);let q=self.quote();let id=q["id"].as_u64().unwrap();self.log.append(json!({"kind":"intent","qid":id,"quote":q,"at":stamp(base+3000)})).unwrap();self.log.append(json!({"kind":"attempt","qid":id,"at":stamp(base+3000)})).unwrap();assert!(self.model.track_attempt(&self.bank,&self.log,id,BASE+base+3000).unwrap());let key=Key{exchange:"101".into(),market:"101".into(),side:"YES".into(),action:"buy".into(),quantity:q["quantity"].as_u64().unwrap(),limit_units:400_000,spread_ticks:10,distance_ticks:0};(q,key)}
 fn actual(&mut self,q:&Value,kind:&str,at:u64,quantity:u64,fill:&str){let id=q["id"].as_u64().unwrap();let e=json!({"type":kind,"source":"official_sig_api_v1","receiptHash":"c".repeat(64),"orderId":id,"actualOrderId":format!("90{id}"),"marketId":"101","exchangeId":"101","side":q["side"],"action":q["action"],"quantity":quantity,"price":q["price"],"fillId":fill,"executedAt":stamp(at),"fee":"0.000000","status":"filled","filledQuantity":q["quantity"],"fillsComplete":true});self.put(e,at);if kind=="actual_order_ack"&&self.log.attempted.contains(&id){self.log.append(json!({"kind":"ack","qid":id,"receipt":{"orderId":format!("90{id}")}})).unwrap();}if kind=="actual_order_terminal"&&self.log.acknowledgments.contains_key(&id){self.log.append(json!({"kind":"closed","qid":id})).unwrap();}}
 fn close_inventory(&mut self,at:u64){let q=self.bank.engine().order_records().into_iter().find(|q|q["retired"]==false&&((q["side"]=="NO"&&q["action"]=="buy")||(q["side"]=="YES"&&q["action"]=="sell"))).expect("owned hedge or exit");let n=q["quantity"].as_u64().unwrap();self.actual(&q,"actual_order_ack",at,n,"");self.actual(&q,"actual_fill",at+1,n,&format!("2{}",q["id"]));self.actual(&q,"actual_order_terminal",at+2,n,"");}
 fn retire_unsubmitted(&mut self,at:u64){let quotes=self.bank.engine().order_records();for q in quotes{let id=q["id"].as_u64().unwrap();if q["retired"]==false&&!self.bank.engine().live_order_bindings().contains_key(&id){self.put(json!({"type":"unsubmitted_intent_retired","source":"moloch_live_dispatcher","receiptHash":"d".repeat(64),"orderId":id,"confirmedNetworkAttempts":0,"deferPlanningForPackage":true}),at);}}}
}
#[test]fn labels_are_unavailable_until_actual_full_fill_and_later_first_executable_book(){let mut f=F::new();let(q,key)=f.start(0);f.actual(&q,"actual_order_ack",3100,2,"");f.actual(&q,"actual_fill",3500,1,"1001");assert_eq!(f.model.estimate(&key,BASE+3500).matured_marks,0);f.actual(&q,"actual_fill",3600,1,"1002");f.actual(&q,"actual_order_terminal",3700,2,"");assert_eq!(f.model.estimate(&key,BASE+4500).matured_marks,0);f.coverage(4600);f.book(4600,4600,"0.420000","0.470000",100);let result=f.model.estimate(&key,BASE+4600);assert_eq!(result.valid_marks,1);assert_eq!(result.mean_conditional_per_share,Some(20_000));assert!(!result.available);assert!(!f.model.estimate(&key,BASE+4500).available);}
#[test]fn shallow_first_horizon_book_cannot_be_replaced_by_later_favorable_depth(){let mut f=F::new();let(q,key)=f.start(0);f.actual(&q,"actual_order_ack",3100,2,"");f.actual(&q,"actual_fill",3500,2,"1001");f.actual(&q,"actual_order_terminal",3600,2,"");f.coverage(4500);f.book(4500,4500,"0.420000","0.470000",1);f.coverage(4600);f.book(4600,4600,"0.490000","0.540000",100);let estimate=f.model.estimate(&key,BASE+4600);assert_eq!(estimate.matured_marks,1);assert_eq!(estimate.valid_marks,0);assert_eq!(estimate.mean_conditional_per_share,None);assert_eq!(f.model.diagnostic_json()["markReasons"]["insufficient_full_depth"],1);}
#[test]fn gap_censors_pending_label_even_when_later_capture_recovers(){let mut f=F::new();let(q,key)=f.start(0);f.actual(&q,"actual_order_ack",3100,2,"");f.actual(&q,"actual_fill",3500,2,"1001");f.put(json!({"type":"gap","tournamentId":"cup","marketId":"101","exchangeId":"101"}),4000);f.coverage(4500);f.book(4500,4500,"0.490000","0.540000",100);let e=f.model.estimate(&key,BASE+4500);assert_eq!(e.valid_marks,0);assert_eq!(e.matured_marks,1);assert_eq!(f.model.diagnostic_json()["markReasons"]["gap"],1);}
#[test]fn delayed_fill_observation_does_not_retroactively_cherry_pick_a_prior_book(){let mut f=F::new();let(q,key)=f.start(0);f.actual(&q,"actual_order_ack",3100,2,"");f.coverage(4500);f.book(4500,4500,"0.420000","0.470000",100);let id=q["id"].as_u64().unwrap();f.put(json!({"type":"actual_fill","source":"official_sig_api_v1","receiptHash":"c".repeat(64),"orderId":id,"actualOrderId":format!("90{id}"),"marketId":"101","exchangeId":"101","side":"YES","action":"buy","quantity":2,"price":q["price"],"fillId":"1001","executedAt":stamp(3500),"fee":"0.000000"}),5000);assert_eq!(f.model.estimate(&key,BASE+5000).valid_marks,0);assert_eq!(f.model.diagnostic_json()["markReasons"]["fill_observed_after_target"],1);}
#[test]fn exact_committed_bytes_and_chronological_cursor_are_mandatory(){let mut f=F::new();let mut event=json!({"type":"tick","receivedAt":stamp(0),"processedAt":stamp(0)});f.bank.accept("actual-fixture",1,&event).unwrap();event["receivedAt"]=json!(stamp(1));assert_eq!(f.model.observe_committed(&f.bank,"actual-fixture",1,&event),Err("EDGE_SOURCE_BYTES_NOT_COMMITTED"));assert_eq!(f.model.diagnostic_json()["disabled"],"EDGE_SOURCE_BYTES_NOT_COMMITTED");}
#[test]fn repeated_committed_fill_receipts_do_not_increase_independent_sample_count(){let mut f=F::new();let(q,key)=f.start(0);f.actual(&q,"actual_order_ack",3100,2,"");f.actual(&q,"actual_fill",3500,2,"1001");f.actual(&q,"actual_fill",3500,2,"1001");f.coverage(4500);f.book(4500,4500,"0.420000","0.470000",100);assert_eq!(f.model.estimate(&key,BASE+4500).valid_marks,1);}
#[test]fn no_fill_terminal_before_window_is_censored_instead_of_a_false_zero_fill_trial(){let mut f=F::new();let(q,key)=f.start(0);f.actual(&q,"actual_order_ack",3100,2,"");let id=q["id"].as_u64().unwrap();f.put(json!({"type":"actual_order_terminal","source":"official_sig_api_v1","receiptHash":"c".repeat(64),"orderId":id,"actualOrderId":format!("90{id}"),"marketId":"101","exchangeId":"101","side":"YES","action":"buy","price":q["price"],"quantity":2,"status":"canceled","filledQuantity":0,"fillsComplete":true}),3200);let e=f.model.estimate(&key,BASE+3200);assert_eq!(e.complete_exposures,0);assert_eq!(e.censored_exposures,1);assert_eq!(e.fill_probability_bps,None);}
fn candidate(id:&str,basis:Basis,gain:i128,cash:i128,horizon:u64,group:&str)->Candidate{Candidate{id:id.into(),basis,net_gain_units:gain,gross_funding_units:cash,capital_locked_units:cash,holding_horizon_ms:horizon,valid_until_ms:1000,risk_groups:vec![group.into()],source_sha256:"a".repeat(64),horizon_source_sha256:"b".repeat(64),write_admissions:1}}
#[test]fn allocation_values_capital_velocity_without_netting_sale_cash_or_overlapping_groups(){let out=allocate(vec![candidate("slow",Basis::StatewiseGuaranteedIncrementalGain,100,1000,100,"same"),candidate("fast",Basis::StatewiseGuaranteedIncrementalGain,20,100,10,"same"),candidate("other",Basis::OwnFillConditionalEstimate,10,100,10,"different")],0,1000,1000,2).unwrap();assert_eq!(out.selected.iter().map(|c|c.id.as_str()).collect::<Vec<_>>(),vec!["fast","other"]);assert_eq!(out.deferred["slow"],"overlapping_risk_group");assert_eq!(out.cash_committed,200);assert!(!out.execution_authority);}
#[test]fn floor_utility_and_cash_release_are_not_guaranteed_incremental_alpha(){/* [0,100] -> [10,90] raises floor10 but has minimum statewise delta -10. */let out=allocate(vec![candidate("floor",Basis::DownsideFloorUtility,10,10,10,"a"),candidate("cash",Basis::ExecutableCashGain,100,10,10,"b"),candidate("benchmark",Basis::LockedVsLiquidationBenchmark,10,10,10,"c")],0,1000,1000,3).unwrap();assert!(out.selected.is_empty());assert_eq!(out.deferred.len(),3);}
#[test]fn gross_cash_and_shared_write_budget_are_independent_fences(){let a=candidate("a",Basis::StatewiseGuaranteedIncrementalGain,10,100,10,"a");let b=candidate("b",Basis::StatewiseGuaranteedIncrementalGain,10,100,10,"b");let out=allocate(vec![a.clone(),b.clone()],0,150,1000,2).unwrap();assert_eq!(out.selected.len(),1);assert_eq!(out.deferred["b"],"gross_cash_budget");let out=allocate(vec![a,b],0,1000,1000,1).unwrap();assert_eq!(out.deferred["b"],"shared_write_budget");}
#[test]fn malformed_cost_sources_and_score_overflow_cannot_promote_a_candidate(){let mut a=candidate("a",Basis::StatewiseGuaranteedIncrementalGain,i128::MAX,100,10,"a");let b=candidate("b",Basis::StatewiseGuaranteedIncrementalGain,1,100,10,"b");assert!(allocate(vec![a.clone(),b],0,1000,1000,2).is_err());a.source_sha256.clear();let out=allocate(vec![a],0,1000,1000,2).unwrap();assert!(out.selected.is_empty());}

#[test]fn two_nonoverlapping_actual_cohorts_enable_only_source_bound_expected_ranking(){let mut f=F::new();let mut key=None;for base in [0,20_000]{let(q,k)=f.start(base);key=Some(k);f.actual(&q,"actual_order_ack",base+3100,2,"");f.actual(&q,"actual_fill",base+3500,2,&format!("1{}",q["id"]));f.actual(&q,"actual_order_terminal",base+3600,2,"");f.coverage(base+4500);f.book(base+4500,base+4500,"0.420000","0.470000",100);f.close_inventory(base+6500);f.retire_unsubmitted(base+9000);}let estimate=f.model.estimate(&key.unwrap(),BASE+29_000);assert!(estimate.available,"{}",estimate.reason);assert_eq!(estimate.valid_marks,2);assert_eq!(estimate.complete_exposures,2);assert_eq!(estimate.conservative_fill_probability_bps,Some(9000));assert!(!estimate.statistical_confidence_claimed);f.coverage(40_000);f.book(40_000,40_000,"0.400000","0.450000",100);let q=f.quote();let qid=q["id"].as_u64().unwrap();assert!(f.model.maker_candidate(&f.bank,qid,None,BASE+40_000).is_err());let costs=ExecutionCosts{inventory_and_partial_risk_units:1000,source_sha256:"e".repeat(64),horizon:CapitalHorizon{milliseconds:120_000,source_sha256:"f".repeat(64)}};let result=f.model.maker_candidate(&f.bank,qid,Some(&costs),BASE+40_000).unwrap();assert!(result.estimated_net_gain_units.unwrap()>0);let candidate=result.candidate.unwrap();assert_eq!(candidate.holding_horizon_ms,120_000);assert_eq!(candidate.basis,Basis::OwnFillConditionalEstimate);assert!(!f.model.estimate(&result.key,BASE+100_000).available);}
#[test]fn one_partial_fill_never_validates_scaling_to_the_full_requested_quantity(){let mut f=F::new();let(q,key)=f.start(0);f.actual(&q,"actual_order_ack",3100,2,"");f.actual(&q,"actual_fill",3500,1,"1001");f.coverage(4500);f.book(4500,4500,"0.490000","0.540000",100);let estimate=f.model.estimate(&key,BASE+4500);assert_eq!(estimate.valid_marks,0);assert_eq!(estimate.fill_probability_bps,None);assert!(!estimate.available);}
